300	     <div style="font-size:.76rem;color:var(--ink-2);line-height:1.6;">
301	       赛狐订单 SKU 已与 海外仓/Temu 主数据自动对齐 <b>${D.inventory.linked_to_orders}</b> 个货号；
302	       ${linkedZero.length?`<span style="color:var(--crit);font-weight:700">${linkedZero.length} 个待发订单命中断货货号，无法履约。</span>`:'当前无待发订单命中断货货号。'}
303	       <br><span style="color:var(--ink-3)">匹配键：内部货号（赛狐 SKU/MSKU ↔ Temu SKU货号 ↔ WMS 仓库代码）</span>
304	     </div>`;
305	
306	  /* ---------- 平台分布 ---------- */
307	  const pd=D.dist.platform, pmax=Math.max(...Object.values(pd));
308	  const porder=Object.keys(pd).sort((a,b)=>pd[b]-pd[a]);
309	  $('#platN').textContent=`${k.total_orders} 单`;
310	  $('#platDist').innerHTML=porder.map(p=>{
311	    const v=pd[p], w=(v/pmax*100).toFixed(1);
312	    return `<div class="distrow"><span class="lb">${esc(p)}</span><div class="track"><div class="fill" style="width:${w}%;background:${platColor(p)}"></div></div><span class="vv">${v} · ${(v/k.total_orders*100).toFixed(0)}%</span></div>`;
313	  }).join('');
314	
315	  /* ---------- 发货时效 ---------- */
316	  $('#sla').innerHTML=`<div><div class="hero">${ls.within24_pct}%</div><div class="sub">${ls.count} 单当日发货率</div></div>
317	    <div style="display:flex;flex-direction:column;gap:6px;">
318	      <span class="pill">中位 ${ls.p50_h}h</span><span class="pill">均值 ${ls.avg_h}h</span></div>
319	    <div style="display:flex;flex-direction:column;gap:6px;">
320	      <span class="pill">P90 ${ls.p90_h}h</span><span class="pill">超24h ${ls.over24} 单</span></div>`;
321	
322	  /* ---------- 订单表 ---------- */
323	  const COLS=[
324	    {k:'包裹号',t:'包裹号'}, {k:'平台',t:'平台'}, {k:'店铺',t:'店铺'},
325	    {k:'订单号',t:'平台单号'}, {k:'SKU',t:'SKU'}, {k:'品名',t:'品名'},
326	    {k:'仓库',t:'仓库'}, {k:'发货渠道',t:'发货渠道'},
327	    {k:'remaining_h',t:'发货倒计时'}, {k:'state',t:'状态'},
328	    {k:'temu_stock',t:'库存'}, {k:'anomalies',t:'异常'},
329	  ];
330	  let sortKey='severity', sortDir=-1;
331	  let stateFilter='all', platFilter=null, q='';
332	
333	  const states=[['all','全部',O.length],['pending','待处理',k.pending],['shipped','已发货',k.shipped],['void','已作废',k.void]];
334	  $('#stateChips').innerHTML=states.map(([v,l,n])=>`<button class="chip ${v==='all'?'on':''}" data-s="${v}">${l} ${n}</button>`).join('');
335	  document.querySelectorAll('#stateChips .chip').forEach(c=>c.onclick=()=>{
336	    stateFilter=c.dataset.s; document.querySelectorAll('#stateChips .chip').forEach(x=>x.classList.toggle('on',x===c)); apply();
337	  });
338	  $('#platChips').innerHTML=`<button class="chip on" data-p="__all">全部平台</button>`+porder.map(p=>`<button class="chip" data-p="${esc(p)}"><span class="pf"><span class="pdot" style="background:${platColor(p)}"></span>${esc(p)}</span></button>`).join('');
339	  function syncPlatChips(){document.querySelectorAll('#platChips .chip').forEach(c=>c.classList.toggle('on',(c.dataset.p===platFilter)||(c.dataset.p==='__all'&&!platFilter)));}
340	  document.querySelectorAll('#platChips .chip').forEach(c=>c.onclick=()=>{platFilter=c.dataset.p==='__all'?null:c.dataset.p; syncPlatChips(); apply();});
341	
342	  $('#thead').innerHTML=COLS.map(c=>`<th data-k="${c.k}">${c.t}</th>`).join('');
343	  document.querySelectorAll('#thead th').forEach(th=>th.onclick=()=>{
344	    const kk=th.dataset.k; if(sortKey===kk)sortDir*=-1; else{sortKey=kk;sortDir=(kk==='remaining_h')?1:-1;} apply();
345	  });
346	
347	  const KW={'待发':['state','pending'],'待处理':['state','pending'],'已发':['state','shipped'],'断货':['anom','stockout'],'卡仓':['anom','stuck_virtual'],'虚拟仓':['anom','stuck_virtual'],'临期':['anom','due_soon'],'超期':['anom','overdue'],'缺渠道':['anom','no_channel'],'无渠道':['anom','no_channel']};
348	  $('#q').oninput=(e)=>{
349	    q=e.target.value.trim().toLowerCase();
350	    for(const key in KW){ if(q.includes(key.toLowerCase())){ const[type,val]=KW[key]; if(type==='state'){stateFilter=val;document.querySelectorAll('#stateChips .chip').forEach(x=>x.classList.toggle('on',x.dataset.s===val));} if(type==='anom'){activeAnom=val;renderAnom();} } }
351	    apply();
352	  };
353	
354	  function countdownCell(o){
355	    const r=o.remaining_h;
356	    if(r==null) return `<span class="cl mono" style="color:var(--ink-3)">—</span>`;
357	    const overdue=r<0, soon=r>=0&&r<24;
358	    const col=overdue?'var(--crit)':soon?'var(--warn)':'var(--good)';
359	    const pct=Math.max(4,Math.min(100,(1-Math.min(Math.abs(r),120)/120)*100));
360	    const lab=overdue?`超期${Math.abs(r).toFixed(1)}h`:`${r.toFixed(1)}h`;
361	    return `<div class="cd"><div class="ct"><div class="cf" style="width:${pct}%;background:${col}"></div></div><span class="cl mono" style="color:${col}">${lab}</span></div>`;
362	  }
363	  function tagCell(o){
364	    if(!o.anomalies.length) return '<span style="color:var(--ink-3);font-size:.72rem">正常</span>';
365	    return `<div class="tags">`+o.anomalies.map(t=>{const r=D.rules[t];const c=r.weight>=90?'crit':r.weight>=40?'warn':'info';return `<span class="tg ${c}" title="${esc(r.desc)}">${esc(r.name)}</span>`;}).join('')+`</div>`;
366	  }
367	  function cell(o,c){
368	    const v=o[c.k];
369	    if(c.k==='平台')return `<span class="pf"><span class="pdot" style="background:${platColor(v)}"></span>${esc(v)}</span>`;
370	    if(c.k==='remaining_h')return countdownCell(o);
371	    if(c.k==='state')return `<span class="st ${v}">${({pending:'待处理',shipped:'已发货',void:'已作废'})[v]}</span>`;
372	    if(c.k==='anomalies')return tagCell(o);
373	    if(c.k==='temu_stock'){ if(v==null)return '<span style="color:var(--ink-3)">—</span>'; return v<=0?`<span class="stock0 mono">${v}⚠</span>`:`<span class="mono">${v}</span>`;}
374	    if(c.k==='品名')return `<span title="${esc(v)}">${esc((v||'').slice(0,14))||'—'}</span>`;
375	    if(c.k==='店铺'||c.k==='发货渠道')return `<span title="${esc(v)}">${esc((v||'—').slice(0,12))}</span>`;
376	    if(c.k==='SKU'||c.k==='包裹号')return `<span class="mono" style="font-size:.74rem">${esc(v)||'—'}</span>`;
377	    if(c.k==='订单号')return `<span class="mono" style="font-size:.72rem;color:var(--ink-2)">${esc(v)||'—'}</span>`;
378	    return esc(v)||'—';
379	  }
380	  function filtered(){
381	    let rows=O.slice();
382	    if(stateFilter!=='all')rows=rows.filter(o=>o.state===stateFilter);
383	    if(platFilter)rows=rows.filter(o=>o['平台']===platFilter);
384	    if(activeAnom)rows=rows.filter(o=>o.anomalies.includes(activeAnom));
385	    if(q)rows=rows.filter(o=>['包裹号','订单号','SKU','MSKU','店铺','品名','产品标题','仓库','发货渠道'].some(f=>String(o[f]||'').toLowerCase().includes(q)));
386	    rows.sort((a,b)=>{
387	      if(sortKey==='remaining_h'||sortKey==='temu_stock'||sortKey==='severity'){
388	        let x=a[sortKey],y=b[sortKey]; x=x==null?9e9:x; y=y==null?9e9:y; if(x!==y)return (x-y)*sortDir;
389	        return (b.severity-a.severity);
390	      }
391	      return String(a[sortKey]||'').localeCompare(String(b[sortKey]||''))*sortDir || (b.severity-a.severity);
392	    });
393	    return rows;
394	  }
395	  function apply(){
396	    const rows=filtered();
397	    $('#tbody').innerHTML= rows.length? rows.map(o=>{
398	      const sev=o.severity>=90?'sev-crit':o.severity>=40?'sev-warn':o.severity>0?'sev-info':'';
399	      return `<tr class="${sev}">`+COLS.map(c=>`<td>${cell(o,c)}</td>`).join('')+`</tr>`;
400	    }).join('') : `<tr><td colspan="${COLS.length}" class="empty">无匹配订单</td></tr>`;
401	    $('#rowN').textContent=`${rows.length} / ${O.length} 单`;
402	    $('#footInfo').textContent=`显示 ${rows.length} 单`+(activeAnom?` · 异常：${D.rules[activeAnom].name}`:'')+(platFilter?` · 平台：${platFilter}`:'');
403	  }
404	  apply();
405	
406	  /* ---------- 导出催发清单 ---------- */
407	  $('#exportBtn').onclick=()=>{
408	    const rows=O.filter(o=>o.severity>=40).sort((a,b)=>b.severity-a.severity);
409	    const cols=['包裹号','平台','店铺','订单号','SKU','品名','仓库','发货渠道','剩余发货时间','跟踪号'];
410	    const heads=['包裹号','平台','店铺','平台单号','SKU','品名','仓库','发货渠道','发货倒计时','运单号','异常'];
411	    const q2=(s)=>`"${String(s==null?'':s).replace(/"/g,'""')}"`;
412	    let csv='﻿'+heads.join(',')+'\n';
413	    rows.forEach(o=>{ const tags=o.anomalies.map(t=>D.rules[t].name).join('|'); csv+=cols.map(c=>q2(o[c])).concat(q2(tags)).join(',')+'\n'; });
414	    const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));
415	    a.download='催发清单_'+(D.meta.reference_now||'').slice(0,10)+'.csv';a.click();
416	  };
417	
418	  /* ---------- 主题切换 ---------- */
419	  $('#ttoggle').onclick=()=>{
420	    const cur=document.documentElement.getAttribute('data-theme');
421	    const next=cur==='dark'?'light':cur==='light'?'':'dark';
422	    if(next)document.documentElement.setAttribute('data-theme',next); else document.documentElement.removeAttribute('data-theme');
423	  };
424	})();
425	</script>
426	</body>

